// Where a line goes in a notes comment of a spec issue („For the Release PR“, „Waiting for the user“; docs/agents/delivery.md
// § Issues), for scripts/issue-note.mjs. In 0.18 an appended line landed below the comment's „Generated by“ footer (#833).

/** A section starts on a bold line (`**Asks the user for:**`) or a heading; the footer on a `---` line. */
const startsSection = line => /^(\*\*|#{1,6} )/.test(line)
const isFooter = line => line.trim() === '---'

/**
 * The comment's text with `line` added: at the end of the section whose first line names `section`, or, without a
 * section, at the end of the text above the footer. A section not found is opened above the footer as `**<section>:**`.
 * @param {string} body
 * @param {string} line
 * @param {string} [section]
 * @returns {string}
 */
export function withLine(body, line, section) {
  const lines = body.split(/\r?\n/)
  const footer = lines.findIndex(isFooter)
  const end = footer === -1 ? lines.length : footer
  /** The index after the last non-empty line before `stop`, from `from` on. */
  const afterLastText = (from, stop) => {
    let at = stop
    while (at > from && lines[at - 1]?.trim() === '') at--
    return at
  }
  if (section === undefined) {
    const at = afterLastText(0, end)
    lines.splice(at, 0, line)
    return lines.join('\n')
  }
  const start = lines.findIndex((text, index) => index < end && startsSection(text) && text.includes(section))
  if (start === -1) {
    const at = afterLastText(0, end)
    lines.splice(at, 0, '', `**${section}:**`, line)
    return lines.join('\n')
  }
  const next = lines.findIndex((text, index) => index > start && (startsSection(text) || isFooter(text)))
  lines.splice(afterLastText(start, next === -1 ? lines.length : next), 0, line)
  return lines.join('\n')
}
